<script setup>
import {ref,watch,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api} from '../lib/api'
import {useLearning} from '../stores/learning'
import {useStudyActivity} from '../composables/useStudyActivity'
import GameHeader from '../components/GameHeader.vue'
const route=useRoute(),router=useRouter(),study=useLearning(),lesson=ref(null),error=ref(''),answers=ref({}),feedback=ref(null),busy=ref(false),practiced=ref(false)
const completed=computed(()=>lesson.value?.items.filter(x=>x.completed).length??0)
useStudyActivity(()=>lesson.value?{kind:'lesson',subject:route.params.subject,unit:Number(route.params.unit)}:null)
watch(()=>route.fullPath,async(_,previous,onCleanup)=>{const controller=new AbortController();onCleanup(()=>controller.abort());lesson.value=null;error.value='';answers.value={};feedback.value=null;practiced.value=false;try{const result=await api('/lesson/'+route.params.subject+'/'+route.params.unit,{signal:controller.signal});if(!controller.signal.aborted)lesson.value=result}catch(e){if(e.name!=='AbortError')error.value=e.message}},{immediate:true})
async function finish(){if(busy.value)return;busy.value=true;error.value='';try{const result=await api('/lesson/'+route.params.subject+'/'+route.params.unit+'/complete',{method:'POST',body:{answers:answers.value}});feedback.value=result;if(result.passed)lesson.value.items.forEach(x=>x.completed=true)}catch(e){error.value=e.message}finally{busy.value=false}}
async function quiz(){if(await study.startQuiz(route.params.subject,'all',Number(route.params.unit)))router.push('/quiz?resume=1');else error.value=study.error}
</script>
<template><GameHeader tag="LEARNING LAB" :title="lesson?.title??'학습 단원'" description="개념 이해 → 예제 분석 → 직접 실습 → 이해 확인 순서로 학습해요. 학습 완료 자체에는 포인트가 지급되지 않습니다."/><p v-if="error" class="notice" role="alert">{{error}}</p><div v-if="lesson" class="lesson-lab"><div class="lesson-summary panel"><div><b>약 {{lesson.guide.minutes}}분 · {{completed}} / {{lesson.items.length}}개 학습 완료</b><p>이미 완료한 기록은 그대로 유지됩니다. 이해 확인을 통과하면 단원의 학습 항목을 한 번에 완료합니다.</p></div><div class="toolbar"><button @click="quiz">이 단원 퀴즈 풀기</button><RouterLink to="/student" class="button light">진도 목록으로</RouterLink></div></div><section class="panel"><p class="eyebrow">01 / 핵심 개념</p><h2>{{lesson.guide.title}}</h2><ul class="lesson-goals"><li v-for="goal in lesson.guide.goals" :key="goal">{{goal}}</li></ul><article v-for="concept in lesson.guide.concepts" :key="concept.title" class="lesson-concept"><h3>{{concept.title}}</h3><p>{{concept.body}}</p></article></section><section class="panel"><p class="eyebrow">02 / 예제 따라가기</p><h2>실행 전에 결과를 예상해 보세요</h2><pre class="lesson-code"><code>{{lesson.guide.example.code}}</code></pre><p class="lesson-explanation">{{lesson.guide.example.explanation}}</p><small>실행은 본인의 IDE·연습 DB에서 진행합니다. 이 화면은 코드를 실행하지 않습니다.</small></section><section class="panel"><p class="eyebrow">03 / 직접 실습</p><h2>{{lesson.guide.practice.task}}</h2><ol><li v-for="step in lesson.guide.practice.steps" :key="step">{{step}}</li></ol><details class="lesson-solution"><summary>직접 해 본 뒤 풀이 가이드 보기</summary><pre><code>{{lesson.guide.practice.solution}}</code></pre></details><label class="check-line"><input v-model="practiced" type="checkbox"/>실습하고 결과와 이유를 확인했어요</label></section><section class="panel"><p class="eyebrow">04 / 이해 확인</p><h2>외운 답보다 이유를 확인해요</h2><form @submit.prevent="finish"><fieldset v-for="(q,index) in lesson.guide.checks" :key="q.id" class="lesson-check"><legend>{{index+1}}. {{q.prompt}}</legend><label v-for="(option,i) in q.options" :key="i"><input v-model="answers[q.id]" :value="i" :name="q.id" type="radio" required @change="feedback=null"/>{{option}}</label><p v-if="feedback" role="status">{{feedback.feedback[index].correct?'✓ 정답':'다시 생각해 보세요'}} · {{feedback.feedback[index].explanation}}</p></fieldset><button :disabled="busy||!practiced||!lesson.guide.checks.length">{{busy?'확인 중…':'이해 확인하고 단원 학습 완료'}}</button><p v-if="!practiced">실습 확인 후 이해 확인을 제출할 수 있어요.</p><p v-if="feedback" role="status">{{feedback.passed?'✓ 단원 학습 완료! 퀴즈로 적용해 보세요.':'설명을 읽고 틀린 항목을 다시 선택해 보세요.'}}</p></form></section><details class="panel lesson-reference"><summary>단원별 개념 복습 카드 · {{lesson.items.length}}개</summary><article v-for="item in lesson.items" :key="item.id"><h3>{{item.title}}</h3><p>{{item.explanation}}</p><small>{{item.completed?'✓ 학습 완료':'아직 학습 전'}}</small></article></details><a v-if="/^https:\/\//.test(lesson.source)" :href="lesson.source" target="_blank" rel="noopener">공식 문서에서 더 보기 ↗</a></div><RouterLink v-else-if="error" to="/student" class="button">내 학습으로</RouterLink></template>
<style scoped>
.lesson-lab{display:grid;gap:18px;max-width:1100px;margin:0 auto;padding-bottom:20px}.lesson-lab>.panel{padding:clamp(16px,3vw,30px);min-width:0}.lesson-summary{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px}.lesson-lab p,.lesson-lab li{line-height:1.9;font-size:14px}.lesson-lab h2{font-size:21px;line-height:1.7}.lesson-concept{padding:12px 0;border-top:1px solid var(--rpg-mid)}.lesson-concept h3{font-size:17px}.lesson-goals{background:var(--rpg-soft);padding:16px 16px 16px 36px;border-radius:8px}.lesson-code,.lesson-solution pre{white-space:pre;overflow:auto;max-width:100%;padding:20px;border-radius:10px;background:#182436;color:#e2f1ff;font:13px/1.8 Consolas,monospace;tab-size:2}.lesson-explanation{padding:14px;background:var(--rpg-soft);border-left:4px solid var(--rpg-edge)}.lesson-solution{margin:18px 0}.lesson-solution summary{cursor:pointer;font-weight:bold}.lesson-check{margin:16px 0;padding:16px;border:2px solid var(--rpg-mid);border-radius:10px;min-width:0}.lesson-check legend{font-weight:bold;line-height:1.8}.lesson-check label{display:flex;gap:10px;align-items:start;line-height:1.8;margin:10px 0}.lesson-check input{width:18px;height:18px;flex:none}.lesson-reference article{border-bottom:1px solid var(--rpg-mid);padding:14px 0}@media(max-width:600px){.lesson-lab{gap:12px}.lesson-lab h2{font-size:17px}.lesson-lab p,.lesson-lab li,.lesson-check label{font-size:12px}.lesson-code{font-size:11px;padding:12px}}
</style>

<style scoped>
.lesson-lab .toolbar{display:flex;justify-content:flex-start;align-items:center;gap:10px;flex-wrap:wrap;margin:0}.lesson-lab .toolbar>button,.lesson-lab .toolbar>.button{box-sizing:border-box;flex:0 0 auto;width:max-content;max-width:100%;min-width:0;min-height:40px;height:auto;margin:0;padding:10px 14px;font-size:12px;line-height:1.4;white-space:normal;overflow-wrap:anywhere;text-align:center}.lesson-summary>div:first-child{flex:1 1 380px;min-width:0}.lesson-summary .toolbar{flex:0 1 auto}.lesson-summary p{margin:8px 0 0}.lesson-lab form>button{width:max-content;max-width:100%;min-width:0;font-size:12px;padding:11px 16px;line-height:1.5;white-space:normal}@media(max-width:600px){.lesson-summary{gap:14px}.lesson-summary>div:first-child{flex-basis:100%}.lesson-lab .toolbar>button,.lesson-lab .toolbar>.button{min-height:38px;padding:9px 12px;font-size:11px}.lesson-lab form>button{font-size:11px}}
</style>
